#[path="profile.rs"] mod profile;
use profile::*;
#[test] fn topology(){assert_eq!(T6040.enabled_cores(),Some(16));assert_eq!(T8132.enabled_cores(),Some(10));assert_eq!(T6040.variant,Variant::S);assert!(!T6040.normal_startup_implemented);assert!(profile(0x9999).is_none());}
#[test] fn cluster_0(){let c=&[(0, 125), (338000000, 610), (618000000, 660), (796000000, 695), (924000000, 725), (952000000, 770), (1056000000, 770), (1062000000, 815), (1182000000, 815), (1182000000, 870), (1312000000, 870), (1242000000, 915), (1380000000, 915), (1326000000, 955), (1470000000, 955), (1578000000, 1025)];let s=&[(0, 810), (338000000, 810), (618000000, 810), (796000000, 810), (924000000, 810), (952000000, 810), (1056000000, 810), (1062000000, 815), (1182000000, 815), (1182000000, 870), (1312000000, 870), (1242000000, 915), (1380000000, 915), (1326000000, 955), (1470000000, 955), (1578000000, 1025)];let mut out=[Step::default();16];assert_eq!(ladder(c,s,&mut out),Some(11));assert_eq!(out[0].high_mhz,0);assert_eq!(out[0].low_mhz,0);assert_eq!(out[0].core_voltage,125);assert_eq!(out[1].high_mhz,338);assert_eq!(out[1].low_mhz,338);assert_eq!(out[1].core_voltage,610);assert_eq!(out[2].high_mhz,618);assert_eq!(out[2].low_mhz,618);assert_eq!(out[2].core_voltage,660);assert_eq!(out[3].high_mhz,796);assert_eq!(out[3].low_mhz,796);assert_eq!(out[3].core_voltage,695);assert_eq!(out[4].high_mhz,924);assert_eq!(out[4].low_mhz,924);assert_eq!(out[4].core_voltage,725);assert_eq!(out[5].high_mhz,1056);assert_eq!(out[5].low_mhz,952);assert_eq!(out[5].core_voltage,770);assert_eq!(out[6].high_mhz,1182);assert_eq!(out[6].low_mhz,1062);assert_eq!(out[6].core_voltage,815);assert_eq!(out[7].high_mhz,1312);assert_eq!(out[7].low_mhz,1182);assert_eq!(out[7].core_voltage,870);assert_eq!(out[8].high_mhz,1380);assert_eq!(out[8].low_mhz,1242);assert_eq!(out[8].core_voltage,915);assert_eq!(out[9].high_mhz,1470);assert_eq!(out[9].low_mhz,1326);assert_eq!(out[9].core_voltage,955);assert_eq!(out[10].high_mhz,1578);assert_eq!(out[10].low_mhz,1578);assert_eq!(out[10].core_voltage,1025);}
#[test] fn cluster_1(){let c=&[(0, 125), (338000000, 605), (618000000, 645), (796000000, 690), (924000000, 720), (952000000, 765), (1056000000, 765), (1062000000, 805), (1182000000, 805), (1182000000, 855), (1312000000, 855), (1242000000, 915), (1380000000, 915), (1326000000, 970), (1470000000, 970), (1578000000, 1040)];let s=&[(0, 810), (338000000, 810), (618000000, 810), (796000000, 810), (924000000, 810), (952000000, 810), (1056000000, 810), (1062000000, 810), (1182000000, 810), (1182000000, 855), (1312000000, 855), (1242000000, 915), (1380000000, 915), (1326000000, 970), (1470000000, 970), (1578000000, 1040)];let mut out=[Step::default();16];assert_eq!(ladder(c,s,&mut out),Some(11));assert_eq!(out[0].high_mhz,0);assert_eq!(out[0].low_mhz,0);assert_eq!(out[0].core_voltage,125);assert_eq!(out[1].high_mhz,338);assert_eq!(out[1].low_mhz,338);assert_eq!(out[1].core_voltage,605);assert_eq!(out[2].high_mhz,618);assert_eq!(out[2].low_mhz,618);assert_eq!(out[2].core_voltage,645);assert_eq!(out[3].high_mhz,796);assert_eq!(out[3].low_mhz,796);assert_eq!(out[3].core_voltage,690);assert_eq!(out[4].high_mhz,924);assert_eq!(out[4].low_mhz,924);assert_eq!(out[4].core_voltage,720);assert_eq!(out[5].high_mhz,1056);assert_eq!(out[5].low_mhz,952);assert_eq!(out[5].core_voltage,765);assert_eq!(out[6].high_mhz,1182);assert_eq!(out[6].low_mhz,1062);assert_eq!(out[6].core_voltage,805);assert_eq!(out[7].high_mhz,1312);assert_eq!(out[7].low_mhz,1182);assert_eq!(out[7].core_voltage,855);assert_eq!(out[8].high_mhz,1380);assert_eq!(out[8].low_mhz,1242);assert_eq!(out[8].core_voltage,915);assert_eq!(out[9].high_mhz,1470);assert_eq!(out[9].low_mhz,1326);assert_eq!(out[9].core_voltage,970);assert_eq!(out[10].high_mhz,1578);assert_eq!(out[10].low_mhz,1578);assert_eq!(out[10].core_voltage,1040);}
#[test] fn rejects_bad_rows(){let mut out=[Step::default();2];assert_eq!(ladder(&[(1000001,1)],&[(1000001,1)],&mut out),None);assert_eq!(ladder(&[(1000000,2),(2000000,1)],&[(1000000,2),(2000000,1)],&mut out),None);assert_eq!(ladder(&[(1000000,1)],&[],&mut out),None);}

#[test] fn t8132_fixture() {let c:Vec<_>=(0..11).map(|i|(i*1000000,i+1)).collect();let mut out=[Step::default();11];assert_eq!(ladder(&c,&c,&mut out),Some(11));assert_eq!(out[10].high_mhz,10);}
#[test] fn bad_mask(){let bad=Profile{chip:0x6040,variant:Variant::S,slots_per_cluster:10,masks:&[0x400],register_bytes:0,normal_startup_implemented:false};assert_eq!(bad.enabled_cores(),None);}
